struct LoopProgressCondition {
  var currentToken: Lexer.Lexeme?

  init() {}

  /// Implementation of the above `evaluate` methods.
  fileprivate mutating func evaluate(_ currentToken: Lexer.Lexeme) -> Bool {
    defer {
      self.currentToken = currentToken
    }

